import React, {useState, useEffect} from 'react';
import {Alert, PermissionsAndroid, Platform, View} from 'react-native';
import DocumentScanner, {
  ResponseType,
  ScanDocumentResponseStatus,
} from 'react-native-document-scanner-plugin';

type Props = {
  onScannedImage?: (image: string) => void;
};

const ScanDocument = ({onScannedImage}: Props) => {
  const scanDocument = async () => {
    if (
      Platform.OS === 'android' &&
      (await PermissionsAndroid.request(
        PermissionsAndroid.PERMISSIONS.CAMERA,
      )) !== PermissionsAndroid.RESULTS.GRANTED
    ) {
      Alert.alert(
        'Error',
        'User must grant camera permissions to use document scanner.',
      );
      onScannedImage?.('');
      return;
    }
    // start the document scanner
    try {
      const {scannedImages, status} = await DocumentScanner.scanDocument({
        maxNumDocuments: 1,
        responseType: ResponseType.Base64,
      });

      // get back an array with scanned image file paths
      if (scannedImages && scannedImages.length > 0) {
        // set the img src, so we can view the first scanned image
        if (status === ScanDocumentResponseStatus.Success) {
          onScannedImage?.(scannedImages[0]);
        }
      } else {
        onScannedImage?.('');
      }
    } catch (error) {
      onScannedImage?.('');
    }
  };

  useEffect(() => {
    // call scanDocument on load
    scanDocument();
  }, []);

  return <View></View>;
};

export default ScanDocument;
